 '{"Kia": ["Rio", "Sportage", "Sorento"], "Hyundai": ["Solaris", "Creta", "Santa Fe"], "Toyota": ["Camry", "RAV4", "Land Cruiser Prado"], "Volkswagen": ["Polo", "Tiguan"], "Skoda": ["Octavia", "Rapid"], "Lada (ВАЗ)": ["Vesta", "Granta"]}'::jsonb,
 21, TRUE, 900, '', 'на складе'),

('videoregistrator-s-radar-detektorom', 'gw-dvrrad',
 'Видеорегистратор с радар-детектором и GPS',
 'Видеорегистраторы', 11400, NULL, '', '1 год', 2005, 2026, NULL,
 '["https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/a31666ff-1782-4809-aba8-74860ea280c7.jpg"]'::jsonb,
 '["Комбо-устройство три в одном: регистратор, радар-детектор и GPS-информер. Заранее предупреждает о камерах контроля скорости голосом и на экране — с указанием ограничения на участке.", "Запись Super HD 2304x1296 — номера читаются даже на встречной полосе. База камер обновляется, сигнатурный режим отсекает ложные срабатывания от автоматических дверей и парктроников."]'::jsonb,
 '[["Разрешение:", "Super HD 2304x1296"], ["Экран:", "3 дюйма"], ["Радар-детектор", "сигнатурный"], ["База камер", "с обновлением"]]'::jsonb,
